import{_ as a,c as t,o,ag as r}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Community Recommended Pathways","description":"","frontmatter":{"title":"Community Recommended Pathways"},"headers":[],"relativePath":"community/community-recommended-pathways.md","filePath":"community/community-recommended-pathways.md","lastUpdated":null}'),i={name:"community/community-recommended-pathways.md"};function n(s,e,l,c,h,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="community-recommended-pathways" tabindex="-1">Community Recommended Pathways <a class="header-anchor" href="#community-recommended-pathways" aria-label="Permalink to &quot;Community Recommended Pathways&quot;">​</a></h1><h2 id="tech-pathways-return-to-unit" tabindex="-1">Tech Pathways (Return to Unit) <a class="header-anchor" href="#tech-pathways-return-to-unit" aria-label="Permalink to &quot;Tech Pathways (Return to Unit)&quot;">​</a></h2><h3 id="gap-tron" tabindex="-1">GAP - TRON <a class="header-anchor" href="#gap-tron" aria-label="Permalink to &quot;GAP - TRON&quot;">​</a></h3><p>The GAP-TRON program is a 9-month digital up-skilling initiative, starting with a 3-month full-time boot camp followed by a 6-month apprenticeship with one of the program’s teams.</p><h3 id="how-to-apply" tabindex="-1">How to Apply <a class="header-anchor" href="#how-to-apply" aria-label="Permalink to &quot;How to Apply&quot;">​</a></h3><p>Visit <a href="https://url.irregular.chat/msuite" target="_blank" rel="noreferrer">GAP-TRON Application Portal</a>.</p><h3 id="the-software-factory" tabindex="-1">The Software Factory <a class="header-anchor" href="#the-software-factory" aria-label="Permalink to &quot;The Software Factory&quot;">​</a></h3><p>The Software Factory, part of Army Futures Command, provides opportunities for cohorts to develop their software and technical skills with utilization back at their units. Participants spend about a year away from their units, with training hosted at Austin Community College in Austin, Texas.</p><p>The initiative began in January 2021, with new cohorts starting every six months, consisting of approximately 25 Soldiers and 5 DA Civilians. The Software Factory emphasizes a modern, flat organizational structure where skills and contributions eclipse rank. The motto is &quot;By Soldiers, For Soldiers.&quot;</p><h3 id="positions-available" tabindex="-1">Positions Available <a class="header-anchor" href="#positions-available" aria-label="Permalink to &quot;Positions Available&quot;">​</a></h3><ul><li><p>Software Developers</p></li><li><p>UI/UX Designers</p></li><li><p>Product Managers</p></li><li><p>Platform Engineers</p></li></ul><h3 id="how-to-apply-1" tabindex="-1">How to Apply <a class="header-anchor" href="#how-to-apply-1" aria-label="Permalink to &quot;How to Apply&quot;">​</a></h3><p>Contact the designated chat for application details.</p><p>For insights into roles, interviews with participants from the pilot project (NIPR login required):</p><ul><li><p><a href="https://web.microsoftstream.com/video/334a1383-346a-4019-b8e5-e738199629cd" target="_blank" rel="noreferrer">Product Manager Interview</a></p></li><li><p><a href="https://web.microsoftstream.com/video/4c0086ce-5bf5-4275-b9f0-3edc4376735b" target="_blank" rel="noreferrer">UI/UX Designer Interview</a></p></li><li><p><a href="https://web.microsoftstream.com/video/e4156126-7d05-464c-93db-6b1b5326506a" target="_blank" rel="noreferrer">Software Engineer Interview</a></p></li><li><p><a href="https://web.microsoftstream.com/video/87f43df4-28cd-4b81-9f3e-7417f0a5197a" target="_blank" rel="noreferrer">Platform Engineer Interview</a></p></li></ul><h3 id="certifications" tabindex="-1">Certifications <a class="header-anchor" href="#certifications" aria-label="Permalink to &quot;Certifications&quot;">​</a></h3><p>Refer to the <a href="/general/certifications.html">Resources</a> page for more information.</p><h3 id="courses" tabindex="-1">Courses <a class="header-anchor" href="#courses" aria-label="Permalink to &quot;Courses&quot;">​</a></h3><h3 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A&quot;">​</a></h3><h4 id="q-recommend-an-ot-tech-exploitation-class-not-sans" tabindex="-1">Q: Recommend an OT tech exploitation class (not SANS) <a class="header-anchor" href="#q-recommend-an-ot-tech-exploitation-class-not-sans" aria-label="Permalink to &quot;Q: Recommend an OT tech exploitation class (not SANS)&quot;">​</a></h4><p><strong>A: CISA 301v and 401v</strong></p><ul><li><p>These are free online courses. CISA 301v covers OT cybersecurity fundamentals.</p></li><li><p>Advanced OT exploitation training is rare. The Cyber Mentor (TCM) offers a vendor and certification series with excellent reviews and reasonable pricing: <a href="https://academy.tcm-sec.com/courses" target="_blank" rel="noreferrer">TCM Academy</a>.</p></li></ul><h4 id="q-anyone-been-to-jacwc" tabindex="-1">Q: Anyone been to JACWC? <a class="header-anchor" href="#q-anyone-been-to-jacwc" aria-label="Permalink to &quot;Q: Anyone been to JACWC?&quot;">​</a></h4><p><strong>A:</strong></p><ul><li><p>JACWC is a cyber planning course similar to JPP with added cyber methodologies. It has replaced JNAC, which is now defunct.</p></li><li><p>Recommendations:</p><ul><li>CEAC is now included in the 170A WOBC curriculum.</li><li>The Mission Commander Course at the CCOE Cyber Schoolhouse is a joint course and considered a better option.</li></ul></li></ul><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><p>[Training] [Development] [Futures Command] [Training Programs]</p>',27)])])}const u=a(i,[["render",n]]);export{p as __pageData,u as default};
